29	/// Ein geparstes Lastprofil. `id` ist der Workload-Achsen-Wert (= profile_name in der CSV). `records`/`num_operations`
30	/// sind XML-Defaults (Skala); der Aufrufer darf sie mit der Harness-Skala überschreiben.
31	struct LoadProfile {
32	    std::string    id;
33	    std::string    paper_ref;
34	    std::string    catalog_lp_id;
35	    std::string    pretty_name;
36	    std::uint64_t  records        = 0; // XML-Default Load-Records (0 → Aufrufer wählt, typ. = n_ops)
37	    std::uint64_t  num_operations = 0; // XML-Default Run-Ops    (0 → Aufrufer wählt)
38	    WorkloadConfig config{};           // op-mix/dist/neg%/scan aus XML (name bleibt Default; Aufrufer nutzt id)
39	};
