47	// ── Eingabe der EINEN CEB-Eintritts-API. ALLES, was NICHT aus dem Profil kommt (Pfade/Toolchain/Output) ──
48	//    Die WHAT-Konfiguration (Lebewesen/Achsen/Sweeps/SOTA/Working-Set/run_options) liest run_profile selbst
49	//    aus dem Profil (tp). cap/resume/platform/build_version werden aus <run_options> vorbelegt; argv/env darf
50	//    weiterhin uebersteuern (der Treiber-Host setzt die Felder hier vor dem Aufruf).
51	struct RunProfileArgs {
52	    std::filesystem::path    profile_path;     // das comdare_thesis_profile (m3v2_study.profile.xml)
53	    std::filesystem::path    out_csv;          // Ziel-CSV (Header genau EINMAL, alle Paesse darunter)
54	    std::filesystem::path    src_dir;          // perm_<id>.cpp-Ausgabe (per-Binary-Subdir-Basis)
55	    std::filesystem::path    dll_dir;          // perm_<id>.dll-Ausgabe (per-Binary-Subdir-Basis)
56	    ex::CompileFn            compile;          // injizierter Compiler-Aufruf (cl @rsp) — wie BuildOrchestrator
57	    std::vector<std::string> compile_includes; // ungenutzt hier (der Host backt die Includes in compile) — Doku
58	    std::uint64_t            n_ops               = 10000;  // Mess-Workload je dyn-Setting
59	    std::size_t              max_binaries        = 0;      // 0 ⇒ run_options.cap (Profil); sonst Override
60	    std::string              build_version       = "m3v2"; // Resume-Marke (.version-Sidecar)
61	    std::uint32_t            n_repeats           = 3;      // Wiederholungen je (Binary×Setting)
62	    std::size_t              cores_per_build     = 4;      // KF-16b Default
63	    double                   min_free_gb         = 0.0;    // RAM-Admission (0 = aus)
64	    bool                     resume_override_set = false;  // true ⇒ resume kommt aus `resume`, nicht aus <run_options>
65	    bool                     resume              = true;   // Mess-Resume (#139)
66	    std::string              sweep_axis;                 // leer = Basis-Selektion; sonst ein deklarierter <axis_sweep>
67	    std::string              platform_override;          // leer ⇒ <run_options>.platform; sonst Override (CSV-Tag)
68	    std::string              build_version_tag_override; // leer ⇒ <run_options>.build_version; sonst Override (CSV-Tag)
69	    bool                     run_sota_series = true;     // S7b: die <sota_series>-Paesse mitfahren (false = nur Basis)
70	    // Working-Set-Sweep: Default = der Profil-<working_set_sweep>. Ist `working_set_override` gesetzt (>0), ersetzt
71	    // er den Profil-Sweep durch EINEN einzigen N-Wert (rueckwaerts-kompatibel zur alten PS-foreach +
72	    // COMDARE_WORKLOAD_RECORDS, wo das Harness die aeussere N-Schleife selbst faehrt). 0 = Profil-Sweep nutzen.
73	    std::uint64_t working_set_override = 0;
74	    // Achse 2 (#135): XML-Lastprofil-Registry (id → WorkloadConfig). Vom Host via discover_load_profiles gesetzt.
75	    std::map<std::string, wd::WorkloadConfig> workload_registry;
76	    std::vector<std::string>                  workload_values; // nur fuers Log (Achse-2-Werte)
77	};
