90	// Interne Helfer: zaehlt '\n' in einem CSV-Block (resumierte Zeilen liegen als String vor).
91	[[nodiscard]] inline std::size_t count_lines(std::string const& s) {
92	    std::size_t n = 0;
93	    for (char c : s)
94	        if (c == '\n') ++n;
95	    return n;
96	}
