98	/// run_profile — DIE EINE deklarative CEB-Eintritts-API (S7c). Faehrt aus EINEM Profil BEIDE Subsets:
99	///   (1) den BASIS-Pass (permute_axes → source_catalog) und
100	///   (2) je <sota_series> einen SOTA-Reihen-Pass (sota_catalog), getaggt A/B/C,
101	/// ueber EINE vereinigte SourceGenFn (make_union_source_gen) in EINE CSV. Die per-Pass-Iteration ueber
102	/// <working_set_sweep> bleibt erhalten (aeussere N-Schleife). Resume/binary_id-Stabilitaet wie der heutige
103	/// Treiber (run_lazy_static_then_dynamic je Pass; #139-Stamp pro Pass).
104	[[nodiscard]] inline RunProfileResult run_profile(RunProfileArgs const& a) {
105	    RunProfileResult res;
106	
107	    // ── (0) Profil EINMAL parsen (die EINZIGE WHAT-Quelle). ──
108	    std::optional<cx::ThesisProfile> const tp_opt = load_thesis_profile(a.profile_path);
109	    if (!tp_opt) {
110	        std::cerr << "run_profile: Profil '" << a.profile_path.string()
111	                  << "' nicht lesbar (parse_thesis_profile=nullopt) — Abbruch.\n";
112	        res.exit_code = 5;
113	        return res;
114	    }
115	    auto const&             tp        = *tp_opt;
116	    std::string const       mode_name = tp.modes.empty() ? std::string{"m3v2_base"} : tp.modes.front().name;
117	    ProfileRunOptions const ro        = profile_run_options(tp);
118	
119	    // ── (1) Der BASIS-Baum (build_profile_basis_levels = build_axis_levels OHNE tier-Ebene). ──
120	    auto                       factory = std::make_shared<ex::ExperimentNodeFactory>();
121	    ex::ExperimentTree         basis_tree{factory};
122	    std::vector<ex::AxisLevel> basis_levels = build_profile_basis_levels(tp, mode_name, /*with_dynamic=*/true);
123	    // ── (1b) ACHSE 2 (Lastprofil) als DYNAMISCHE Ebene injizieren (STRANG-A-Wiring-Luecke, 2026-06-19).
124	    //    build_axis_levels emittiert die runtime_dynamic-DynDims (concurrency.thread_count / prefetch.hw_prefetcher /
125	    //    repetition.repetition_index), aber NICHT die Lastprofil-Achse (die wird separat ueber discover_load_profiles
126	    //    entdeckt → a.workload_values). Ohne diese Ebene fehlt im setting_label das Segment "workload.workload_id=X";
127	    //    der Iterator faellt dann auf run_observable_perm (fixer Workload, KEIN Zwei-Phasen-Cache-Warmup) zurueck →
128	    //    JEDE Zeile two_phase_valid=0 (Mess-UNGUELTIG). Mit der Ebene laeuft run_workload_perm mit Pflicht-Rollback
129	    //    → two_phase_valid=1. Gleiche Konvention wie die uebrigen DynDims (block_id.variable=value): block_id
130	    //    "workload", variable "workload_id" (lazy_extract_workload_id sucht genau "workload_id="). is_static=false ⇒
131	    //    veraendert die binary_id NICHT (Round-Trip-Gate unberuehrt).
132	    if (!a.workload_values.empty())
133	        basis_levels.push_back(
134	            ex::AxisLevel{"workload", a.workload_values, /*is_static=*/false, "workload_id", "workload"});
135	    basis_tree.build(basis_levels);
136	    ex::StaticBinaryView const basis_view = basis_tree.static_binary_view();
137	
138	    // ── (2) cap/resume/Tags (Profil-Defaults; Override aus den Args). ──
139	    std::size_t eff_cap = a.max_binaries;
140	    if (ro.cap > 0 && a.max_binaries == 0) eff_cap = ro.cap;
141	    bool const        resume = a.resume_override_set ? a.resume : ro.resume;
142	    std::size_t const N      = (std::min)(eff_cap, basis_tree.binary_count());
143	
144	    std::string tag_platform      = a.platform_override.empty()
145	                                        ? (ro.platform.empty() ? std::string{"win-x86_64"} : ro.platform)
146	                                        : a.platform_override;
147	    std::string tag_build_version = a.build_version_tag_override.empty()
148	                                        ? (ro.build_version.empty() ? std::string{"m3v2"} : ro.build_version)
149	                                        : a.build_version_tag_override;
150	
151	    // ── (3) S7a + FF(#168): die EINE vereinigte SourceGenFn (Basis-320 ∪ 4 Achsen-Sweeps ∪ SOTA-Reihen).
152	    //    Reihenfolge unkritisch: Basis-320 ("search_algo=…/migration_policy=migration_none/…"-Pfade) und die
153	    //    Achsen-Sweep-Map (gleicher 19-Achsen-Pfad-Namensraum, ABER andere Auspraegungen wie
154	    //    …/migration_policy=migration_hot_cold/…, die im Basis-320 NICHT vorkommen) sind ueberlappungsfrei (bis auf
155	    //    die Baseline-DLL, die identisch ist → idempotent). SOTA liegt im disjunkten "sota_tier=…"-Raum.
156	    std::map<std::string, std::string> fused = make_all_axis_sweeps_source_map(); // ~16 vertiefte-Achsen-Eintraege
157	    for (auto& [k, v] : build_sota_view_source_map(tp)) fused.emplace(k, std::move(v)); // + SOTA-Reihen (disjunkt)
158	    ex::SourceGenFn const union_gen =
159	        make_union_source_gen(make_catalog_source_gen<FullSourceCatalog>(), std::move(fused));
160	    ex::FreeRamFn ram = ex::make_system_free_ram_fn();
161	
162	    // ── (4) Working-Set-Sweep = die aeussere N-Liste (gilt fuer BEIDE Subsets identisch). Override ⇒ EIN N. ──
163	    std::vector<std::uint64_t> n_sweep;
164	    if (a.working_set_override > 0)
165	        n_sweep.push_back(a.working_set_override); // PS-foreach-Kompatibilitaet
166	    else
167	        n_sweep = profile_working_set_sweep(tp); // Profil-<working_set_sweep>
168	    if (n_sweep.empty()) n_sweep.push_back(0);   // 0 ⇒ Iterator setzt records = n_ops
169	
170	    std::cout << "RUN_PROFILE (CEB-Eintritt): " << a.profile_path.string() << "  id=" << tp.id << " mode=" << mode_name
171	              << "  basis_count=" << basis_tree.binary_count() << " (N=" << N << ")"
172	              << "  sota_series=" << tp.sota_series.size() << "  working_set_n=" << n_sweep.size() << "\n";
173	
174	    // ── EINE CSV; Header GENAU EINMAL; darunter Basis-Pass + SOTA-Paesse (alle N). ──
175	    // M11 (G5-Audit w289llo0o): Stream-Fehlerpruefung. Liess der open() scheitern (Pfad nicht
176	    // schreibbar / Platte voll), waere die CSV stillschweigend leer geblieben → exit_code haette
177	    // faelschlich Erfolg gemeldet. Open-Erfolg jetzt hart geprueft; Schreib-/Flush-Fehler fliessen
178	    // unten (csv.good() nach flush) in den exit_code ein.
179	    std::ofstream csv{a.out_csv.string(), std::ios::trunc};
180	    if (!csv) {
181	        std::cout << "RUN_PROFILE FEHLER: CSV nicht oeffenbar → " << a.out_csv.string() << "\n";
182	        res.exit_code = 1;
183	        return res;
184	    }
185	    csv << ex::lazy_csv_header();
186	
187	    // Gemeinsame Lauf-Config-Vorlage (je Pass kopiert + getaggt). 1 DLL = 1 TU bleibt.
188	    // #171 (2026-06-20): make_cfg traegt zusaetzlich pruefling_type (full/abstract/-). Basis/Sweep uebergeben
189	    // leer ("-"); die SOTA-Paesse uebergeben den aus merge abgeleiteten Typ (sota_catalog::derive_pruefling_type).
190	    auto make_cfg = [&](std::uint64_t ws_n, std::size_t cap_for_pass, std::string const& series,
191	                        std::string const& sweep_axis, std::string const& pruefling_type) {
192	        ex::LazyRunConfig cfg;
193	        cfg.max_binaries              = cap_for_pass;
194	        cfg.n_ops                     = a.n_ops;
195	        cfg.workload_records          = ws_n;
196	        cfg.workload_configs          = a.workload_registry;
197	        cfg.build_version             = a.build_version;
198	        cfg.row_series                = series.empty() ? std::string{"-"} : series;
199	        cfg.row_pruefling_type        = pruefling_type.empty() ? std::string{"-"} : pruefling_type;
200	        cfg.row_sweep_axis            = sweep_axis.empty() ? std::string{"-"} : sweep_axis;
201	        cfg.row_platform              = tag_platform;
202	        cfg.row_build_version         = tag_build_version;
203	        cfg.source_dir                = a.src_dir;
204	        cfg.output_dir                = a.dll_dir;
205	        cfg.cores_per_build           = a.cores_per_build;
206	        cfg.per_binary_subdirs        = true;
207	        cfg.resume_completed_binaries = resume;
208	        cfg.n_repeats                 = a.n_repeats;
209	        cfg.env_limits.thread_count   = 16;
210	        if (a.min_free_gb > 0.0) {
211	            cfg.ram_per_build_bytes     = static_cast<std::uint64_t>(a.min_free_gb * 1024.0 * 1024.0 * 1024.0);
212	            cfg.ram_safety_margin_bytes = cfg.ram_per_build_bytes;
213	        }
214	        return cfg;
215	    };
216	
217	    auto emit = [&](ex::LazyRunResult const& r, std::size_t* row_sink) {
218	        csv << r.resumed_csv_rows;
219	        // #165-B (P-MD8, 2026-06-20): den statistischen Ausreißer-Flag VOR der Emission je Pass befüllen. Lokale,
220	        // mutierbare Kopie der frisch gemessenen Zeilen (LazyRunResult bleibt unberührt); annotate_quality_flags
221	        // setzt nur das additive quality_flag-Feld (0/1) je (binary_id, profile_name)-Gruppe — gate-frei, keine
222	        // bestehende Spalte/kein Messwert berührt. resumed_csv_rows (Alt-Zeilen) bleiben unangetastet (Datenerhaltung).
223	        std::vector<ex::LazyMeasuredRow> rows = r.csv_rows;
224	        ex::annotate_quality_flags(rows);
225	        for (auto const& row : rows) csv << ex::format_csv_row(row);
226	        *row_sink += count_lines(r.resumed_csv_rows) + rows.size();
227	        res.any_measured += r.measured;
228	        res.any_resumed += r.resumed_binaries;
229	    };
230	
231	    // ════════════════════════════════════════════════════════════════════════════════════════════════════
232	    // S7b — PASS 1: BASIS (permute_axes → source_catalog). Selektion = Basis-320 ODER ein deklarierter Sweep.
233	    //
234	    // FF(#168) — VERTIEFTE-ACHSEN-SWEEP: ist `a.sweep_axis` eine der 4 vertieften Achsen (migration_policy/filter/
235	    // value_handle/path_compression), kann der Basis-320-Baum sie NICHT variieren (im Profil je 1 Wert gepinnt →
236	    // level_size==1). Statt der Basis-View baut der Treiber dann einen EIGENEN Sweep-Baum aus axis_sweep_levels(axis)
237	    // — 18 Baseline-Ebenen + die gesweepte Achse VOLL — dessen 19-Achsen-binary_ids die axis_sweep_source_map-Keys
238	    // treffen (in der union_gen). So entsteht je Auspraegung eine REALE distinkte Lebewesen-DLL (z.B. migration_none
239	    // vs migration_hot_cold). Die 4 BASIS-Achsen-Sweeps laufen weiter ueber die Basis-View (dort voll vertreten).
240	    // ════════════════════════════════════════════════════════════════════════════════════════════════════
241	    if (is_deepened_axis(a.sweep_axis)) {
242	        std::vector<ex::AxisLevel> sweep_levels = axis_sweep_levels(a.sweep_axis);
243	        // Dieselben DynamicDims wie der Basis-Baum anhaengen (gleiche thread_count×prefetch×repetition-Variation).
244	        for (auto const& dd : basis_tree.dynamic_filter())
245	            sweep_levels.push_back(ex::AxisLevel{dd.axis, dd.values, /*is_static=*/false, dd.variable, dd.block_id});
246	        auto               sweep_factory = std::make_shared<ex::ExperimentNodeFactory>();
247	        ex::ExperimentTree sweep_tree{sweep_factory};
248	        sweep_tree.build(sweep_levels);
249	        ex::StaticBinaryView const sweep_view = sweep_tree.static_binary_view();
250	        std::size_t const          sweep_n    = sweep_tree.binary_count(); // == |Achsen-Auspraegungen|
251	        std::vector<std::size_t>   ids;
252	        ids.reserve(sweep_n);
253	        for (std::size_t i = 0; i < sweep_n; ++i) ids.push_back(i); // ALLE Auspraegungen (volle Achse)
254	        ex::BuildSelection const sel = ex::select_explicit(std::move(ids));
255	        res.basis_binary_ids         = sel.indices.size();
256	        std::cout << "  [BASIS/deep-sweep] axis=" << a.sweep_axis << " auspraegungen=" << sweep_n
257	                  << " (eigener Sweep-Baum, NICHT Basis-View)\n";
258	        for (std::size_t i = 0; i < sweep_n; ++i)
259	            std::cout << "      sweep binary_id[" << i << "] = " << sweep_view[i].binary_id << "\n";
260	        for (std::uint64_t const ws_n : n_sweep) {
261	            ex::LazyRunConfig       cfg = make_cfg(ws_n, sweep_n, /*series=*/"-", a.sweep_axis, /*pruefling_type=*/"-");
262	            ex::LazyRunResult const r =
263	                ex::run_lazy_static_then_dynamic(sweep_tree, sel, a.compile, union_gen, ram, cfg);
264	            emit(r, &res.basis_rows);
265	        }
266	    } else {
267	        ProfileTaggedSelection const pts = profile_select(tp, basis_levels, basis_view, a.sweep_axis, N);
268	        ex::BuildSelection const     sel = pts.selection;
269	        res.basis_binary_ids             = sel.indices.size();
270	        std::cout << "  [BASIS] label=" << pts.label << " provenance=" << sel.provenance << " indices=" << sel.size()
271	                  << " series=" << pts.series << " sweep=" << pts.sweep_axis << "\n";
272	        for (std::uint64_t const ws_n : n_sweep) {
273	            ex::LazyRunConfig       cfg = make_cfg(ws_n, N, pts.series, pts.sweep_axis, /*pruefling_type=*/"-");
274	            ex::LazyRunResult const r =
275	                ex::run_lazy_static_then_dynamic(basis_tree, sel, a.compile, union_gen, ram, cfg);
276	            emit(r, &res.basis_rows);
277	        }
278	    }
279	
280	    // ════════════════════════════════════════════════════════════════════════════════════════════════════
281	    // S7b — PASS 2..k: je <sota_series> EIN SOTA-Reihen-Lebewesen (einwertiger "sota_tier"-Baum, Tag A/B/C).
282	    //   Disjunkter binary_id-Namensraum ("sota_tier=sota::S::name") → die union_gen liefert die SOTA-Quelle.
283	    // ════════════════════════════════════════════════════════════════════════════════════════════════════
284	    if (a.run_sota_series) {
285	        std::vector<SotaPass> const passes = build_sota_passes(tp);
286	        std::cout << "  [SOTA] real baubare <sota_series>-Paesse = " << passes.size() << " (von "
287	                  << tp.sota_series.size() << " deklariert)\n";
288	        for (auto const& p : passes) {
289	            // Einwertiger Static-Baum: AxisLevel "sota_tier"=<sota_bid> + dieselben DynamicDims wie der Basis-Baum
290	            // (damit die SOTA-Zeilen die gleiche thread_count×prefetch×repetition-Variation tragen).
291	            std::vector<ex::AxisLevel> sota_levels;
292	            sota_levels.push_back(ex::AxisLevel{std::string{kSotaTierAxis}, {p.sota_bid}, /*is_static=*/true, "", ""});
293	            for (auto const& dd : basis_tree.dynamic_filter())
294	                sota_levels.push_back(ex::AxisLevel{dd.axis, dd.values, /*is_static=*/false, dd.variable, dd.block_id});
295	
296	            auto               sota_factory = std::make_shared<ex::ExperimentNodeFactory>();
297	            ex::ExperimentTree sota_tree{sota_factory};
298	            sota_tree.build(sota_levels);
299	            ex::StaticBinaryView const sota_view = sota_tree.static_binary_view();
300	            // EIN Lebewesen je Reihe = view-Index 0. binary_id == p.view_binary_id ("sota_tier=…").
301	            ex::BuildSelection const sel = ex::select_explicit({0});
302	            ++res.sota_binary_ids;
303	            std::cout << "    SOTA-Pass series=" << p.series << " pruefling_type=" << p.pruefling_type
304	                      << " lebewesen=" << p.lebewesen
305	                      << " binary_id=" << (sota_view.empty() ? std::string{"<leer>"} : sota_view[0].binary_id) << "\n";
306	            for (std::uint64_t const ws_n : n_sweep) {
307	                ex::LazyRunConfig cfg =
308	                    make_cfg(ws_n, 1, p.series, /*sweep_axis=*/"", p.pruefling_type); // #171: full/abstract
309	                ex::LazyRunResult const r =
310	                    ex::run_lazy_static_then_dynamic(sota_tree, sel, a.compile, union_gen, ram, cfg);
311	                emit(r, &res.sota_rows);
312	            }
313	        }
314	    }
315	
316	    csv.flush();
317	    // M11 (G5-Audit w289llo0o): nach dem Flush das Stream-Ergebnis pruefen. Ein waehrend des
318	    // Schreibens/Flushens aufgetretener Fehler (Platte voll, IO-Fehler) setzt failbit/badbit und
319	    // wuerde sonst eine still abgeschnittene CSV als Erfolg ausgeben.
320	    bool const csv_ok = csv.good();
321	    std::cout << "RUN_PROFILE fertig: basis_rows=" << res.basis_rows << " sota_rows=" << res.sota_rows
322	              << " (basis_ids=" << res.basis_binary_ids << " sota_ids=" << res.sota_binary_ids << ")"
323	              << " measured=" << res.any_measured << " resumed=" << res.any_resumed
324	              << " csv_ok=" << (csv_ok ? "1" : "0") << " → " << a.out_csv.string() << "\n";
325	
326	    // Exit 0 = mind. 1 (Binary × Setting) real gemessen ODER resumiert (Voll-Resume = gueltiger Lauf)
327	    // UND die CSV fehlerfrei geschrieben+geflusht (M11). Ein Stream-Schreib-/Flush-Fehler erzwingt exit!=0.
328	    res.exit_code = ((res.any_measured > 0 || res.any_resumed > 0) && csv_ok) ? 0 : 1;
329	    return res;
330	}
