207	/// profile_make_axis_sweep — PER-ACHSEN-SWEEP gegen die feste Baseline (alle Ebenen Index 0) variiert GENAU die
208	/// Achse `level_d` ueber ihre Ausprägungen (via StaticBinaryView::flat_index — Achsen-Austausch IM Praefixbaum).
209	/// Funktional identisch zu m3v2::make_axis_sweep, aber der level_d kommt aus profile_axis_level (PROFIL-getrieben).
210	[[nodiscard]] inline ProfileTaggedSelection profile_make_axis_sweep(ex::StaticBinaryView const& view,
211	                                                                    std::size_t level_d, std::string const& axis_name,
212	                                                                    std::size_t cap) {
213	    ProfileTaggedSelection ts;
214	    ts.series     = "-";
215	    ts.sweep_axis = axis_name;
216	    ts.label      = "sweep:" + axis_name;
217	    if (level_d == static_cast<std::size_t>(-1) || level_d >= view.level_count()) {
218	        ts.selection.provenance = "axis_sweep-REFUSED-no-such-level";
219	        return ts;
220	    }
221	    std::size_t const        k = view.level_size(level_d);
222	    std::vector<std::size_t> tuple(view.level_count(), 0); // Baseline: alle Achsen Index 0 (FESTE Baseline-Tier)
223	    std::size_t const        n = (std::min)(cap, k);
224	    std::vector<std::size_t> ids;
225	    ids.reserve(n);
226	    for (std::size_t v = 0; v < n; ++v) {
227	        tuple[level_d] = v;                    // NUR die eine Achse austauschen
228	        ids.push_back(view.flat_index(tuple)); // Praefixbaum-Index (mixed-radix), kein Flach-Tupel
229	    }
230	    ts.selection            = ex::select_explicit(std::move(ids));
231	    ts.selection.provenance = "axis_sweep:" + axis_name;
232	    return ts;
233	}
