235	/// profile_select — die EINE profil-getriebene Selektions-Auswahl, gesteuert ueber `series_axis_or_empty`:
236	///   • ""  / "basis"        → BASIS-320 (profile_make_basis).
237	///   • "<achse>"            → PER-ACHSEN-SWEEP: matcht einen <axis_sweep axis="<achse>"> im Profil; der level_d
238	///                            wird ueber profile_axis_level aus den tier-freien Basis-Levels aufgeloest.
239	/// Verweigert (provenance-Marker) wenn die Achse NICHT als <axis_sweep> deklariert ist (= profil-getrieben:
240	/// nur deklarierte Sweeps sind waehlbar — die hartkodierte axis_to_level-Map ist ersetzt).
241	[[nodiscard]] inline ProfileTaggedSelection profile_select(cx::ThesisProfile const&          tp,
242	                                                           std::vector<ex::AxisLevel> const& static_basis_levels,
243	                                                           ex::StaticBinaryView const&       view,
244	                                                           std::string const& series_axis_or_empty, std::size_t cap) {
245	    if (series_axis_or_empty.empty() || series_axis_or_empty == "basis" || series_axis_or_empty == "index")
246	        return profile_make_basis(view, cap);
247	    // Per-Achsen-Sweep: die Achse MUSS als <axis_sweep> deklariert sein (profil-getriebene Whitelist).
248	    bool declared = false;
249	    for (auto const& sw : tp.axis_sweeps)
250	        if (sw.axis == series_axis_or_empty) {
251	            declared = true;
252	            break;
253	        }
254	    ProfileTaggedSelection ts;
255	    if (!declared) {
256	        ts.sweep_axis           = series_axis_or_empty;
257	        ts.label                = "sweep:" + series_axis_or_empty;
258	        ts.selection.provenance = "axis_sweep-REFUSED-not-declared-in-profile";
259	        return ts;
260	    }
261	    std::size_t const level_d = profile_axis_level(static_basis_levels, series_axis_or_empty);
262	    return profile_make_axis_sweep(view, level_d, series_axis_or_empty, cap);
263	}
